import { polite, forms } from './grammar.js';
export const CONNS = ['그리고', '그런데', '그래서'];
export const SCENES = RAW.map(([id, topic, emoji, pre, v, t, pos, ...nexts]) => {
  const f = forms(v, t, pos), pred = polite(v, t);
  const s = { id, topic, emoji, pre, v, t, pos, pred, a: `${pre} ${pred}.`, next: {} };
  CONNS.forEach((c, i) => { const n = nexts[i]; if (!n) return; const [b, e] = n.split('|');
    s.next[c] = { b: b + '.', e, form: f[c], joined: `${pre} ${f[c]} ${b}.` }; });
  s.forms = f;
  return s;
});
/** every (scene, connective) pair */
export const PAIRS = SCENES.flatMap(s => CONNS.filter(c => s.next[c]).map(c => ({ key: s.id + ':' + c, s, c, ...s.next[c] })));
export const MEANING = {
  그리고: { icon:'➕', name:'더하기', kid:'앞 이야기에 비슷한 이야기를 하나 더 붙여요.', join:'-고', color:'#22b05b' },
  그런데: { icon:'🔄', name:'반대·생각과 달라요', kid:'앞 이야기를 듣고 생각한 것과 다르게 흘러가요.', join:'-는데 (-은데, -ㄴ데)', color:'#ff8a1f' },
  그래서: { icon:'➡️', name:'까닭 → 결과', kid:'앞 일 때문에 뒤 일이 생겨요.', join:'-아서 / -어서 / -해서', color:'#2f7bff' },
};
